local QuestCellNodeLuaPath = 'Game.UI.TrailStage.TrailQuestCellNode'

---@type TrailBattleMgr
local TrailBattleMgr = import('Game.TrailBattle.TrailBattleMgr')


------------ define ------------

---@class TrailQuestDialog
---@field DescriptionText               	UnityEngine.UI.Text
---@field TitleText                      	UnityEngine.UI.Text
---@field BackButton                    	UnityEngine.RectTransform
---@field Icon                          	UnityEngine.RectTransform
---@field Text                          	UnityEngine.UI.Text
---@field RankTitle                     	UnityEngine.UI.Image
---@field QuestsNode                    	UnityEngine.RectTransform @任务节点
---@field QuestPrefabNode               	UnityEngine.RectTransform @任务节点的逻辑
