local TrailQuestDialog = Class("TrailQuestDialog")

function TrailQuestDialog:__init()
    self.isInit = nil
end

function TrailQuestDialog:__delete()
    self.controller = nil
    self.isInit = nil
end

function TrailQuestDialog:Awake()
    --self.controller:SetBackArgument(true)
    UIEventProxy.Create(self.BackButton.gameObject).onPointerClick = function(eventData)
        UIModule.BackDialog()
    end
end

function TrailQuestDialog:FillQuestInfo()
    ---@type PlayerComponent
    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerId = checkInt(playerComp.playerDojo.playerId)
    ---@type TrailBattleMgr
    local trailBattleMgr = TrailBattleMgr:GetInstance()

    ---获取我当前的分值信息
    ---@type TrailEnterDojo
    local enterDojo = trailBattleMgr:GetEnterData()
    local rankInfo = nil
    for i, v in pairs(enterDojo.roomRank) do
        if checkInt(v.playerId) == playerId then
            rankInfo = v
            break
        end
    end
    if enterDojo.quests and rankInfo then
        ---处理flag分数的逻辑
        local teamLength = table.count(rankInfo.team)
        --if checkInt(enterDojo.rank) > 0 then
        if teamLength == 3 then
            ---表示有三组分数 可以参与排名, 组内存在排名，说明有分值
            KTool.SetActive(self.TitleText.gameObject, true)
            KTool.SetActive(self.Text.gameObject, false)
            local rank,group = trailBattleMgr:GetRankGroupBySegment(enterDojo.segment)
            KTool.SetActive(self.Icon.gameObject, true)
            local imageAlterable = KTool.GetOrAddComponent(self.Icon.gameObject, typeof(ImageAlterable))
            imageAlterable:LoadSprite(TrailBattleMgr:GetRankGroupIconPath(group))
            if group == TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.UP_BUTTON then
                ---晋级组
                self.RankTitle.color = XLuaUtils.HexToColor(TrailBattleMgr.CONSTANTS.COLORS.LEVEL_UP)
                self.TitleText.text = localize('当前在晋级组')
            elseif group == TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.STAY_BUTTON then
                self.RankTitle.color = XLuaUtils.HexToColor(TrailBattleMgr.CONSTANTS.COLORS.LEVEL_STAY)
                self.TitleText.text = localize('当前在保级组')
            else
                self.RankTitle.color = XLuaUtils.HexToColor(TrailBattleMgr.CONSTANTS.COLORS.LEVEL_DOWN)
                self.TitleText.text = localize('当前在降级组')
            end
            self.DescriptionText.text = localize('继续挑战刷新最高分可提高排名')
        else
            KTool.SetActive(self.TitleText.gameObject, false)
            self.DescriptionText.text = localize('完成所有挑战后才能参与排名(_pro_/3)', {
                _pro_ = teamLength
            })
        end
        KTool.DestroyGameObjectChildren(self.QuestsNode.gameObject, true)
        print(table.dump(enterDojo.quests))
        for i, questId in pairs(enterDojo.quests) do
            local trailQuestVo = trailBattleMgr:GetTrailQuestVoByRefId(questId)
            local flagKey = 'Flag' .. tostring(i)
            ---@type UnityEngine.RectTransform
            local FlagNodeTrans = self[flagKey]
            local go = KTool.Instantiate(self.QuestsNode.gameObject, self.QuestPrefabNode.gameObject, false)
            KTool.SetActive(go, true)
            local mBehaviour = GetLuaBehaviour(go, QuestCellNodeLuaPath)
            if mBehaviour then
                if isNull(mBehaviour.Env) then
                    mBehaviour:Init()
                end
                ---@type TrailQuestCellNode
                local env = mBehaviour.Env
                local isLocked = true
                if teamLength == 0 and i == 1 then
                    isLocked = false
                else
                    if rankInfo.team[tostring(questId)] then
                        ----取出当前关卡的数据
                        isLocked = false
                    else
                        ---判断前一个关卡是否存在分值
                        local preQuestId = enterDojo.quests[i - 1]
                        if rankInfo.team[tostring(preQuestId)] and checkInt(rankInfo.team[tostring(preQuestId)].passed) == 1 then
                            ---表示已通关前置关卡可以解锁
                            isLocked = false
                        end
                    end
                end
                print(table.dump(enterDojo))
                env:FreshUI(i, trailQuestVo, isLocked, enterDojo.conditions)

                if not isNull(FlagNodeTrans) then
                    ---@type Engine.UI.ImageAlterable
                    local imageAlterable = KTool.GetOrAddComponent(FlagNodeTrans.gameObject, typeof(ImageAlterable))
                    local textTrans = FlagNodeTrans.transform:Find('PointNode/PointText')
                    ---@type UnityEngine.UI.Text
                    local textComp  = KTool.GetComponent(textTrans.gameObject, typeof(CS.UnityEngine.UI.Text))
                    if isLocked then
                        ----锁定状态的情况下
                        imageAlterable:LoadSprite('uiatlas/common/common_ico_lock_1.png')
                    else
                        if rankInfo.team[tostring(questId)] then
                            ---显示可以更新进度
                            imageAlterable:LoadSprite('uiatlas/trailstage/competition_main_ico_done.png')
                            textComp.text = tostring(math.floor(checkInt(rankInfo.team[tostring(questId)].score)))
                        else
                            imageAlterable:LoadSprite('uiatlas/trailstage/competition_main_ico_dot.png')
                            textComp.text = '?????'
                        end
                    end
                end
            end
        end
    end
end

--刷新试炼关卡
function TrailQuestDialog:OnRefeshTrailQuestDialog(body)
    if self.isInit then
        return
    end
    self:FillQuestInfo()
end

function TrailQuestDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.EventRefeshTrailQuestDialog = Events.AddListener(Constants.EventNames.RefeshTrailQuestDialog, Bind(self, self.OnRefeshTrailQuestDialog))
        
        local trailBattleMgr = TrailBattleMgr:GetInstance()
        if not trailBattleMgr.initialed then
            return    
        end
        self.isInit = true
        self:FillQuestInfo()
    end))
    return coWait
end

function TrailQuestDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self) then
            Events.RemoveListener(Constants.EventNames.RefeshTrailQuestDialog, self.EventRefeshTrailQuestDialog)
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return TrailQuestDialog